import {escapeHtml as h,number} from './domain.js';
import {civilizationBadge} from './art.js';
import {civilizationInvestmentView} from './progression.js';
import {capacityBlocks} from './economy.js';
export const compactPopulation=value=>new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(Math.max(0,Number(value)||0));
const money=n=>number(n)+' Þ';
const errorBox='<p class="form-error" role="alert" hidden></p>';
export function planetCapacityQuote(capacity,quantity,prices){const q=Number(quantity);if(!Number.isInteger(q)||q<1||q>200-capacity)return null;let sum=0;for(let i=1;i<=q;i++){const price=Number(prices[capacity+i]);if(!Number.isFinite(price))return null;sum+=price;}return sum;}
export function planetManagementSections(p,progression,overview,pendingPurchase,pendingGovernance,technology){
 const locked=p.governance_changed_at&&new Date(p.governance_changed_at).getTime()+72*3600000>Date.now();
 const techWorld=technology?.planets.find(w=>w.id===p.id),growth=techWorld?.growth;
 const politics=p.governance==='conseil',trade=overview?.planets.find(w=>w.id===p.id),capacity=trade?.capacity??p.trade_capacity,used=trade?.used||0,available=trade?.available??capacity,prices=overview?.prices||{};
 const civilization=progression?.planets.find(w=>w.id===p.id),quote=capacity<200?planetCapacityQuote(capacity,1,prices):null;
 return `<div class="planet-sections planet-management"><section class="stat-section"><div class="section-heading"><h3>Politique & civilisation</h3></div><div class="planet-control-module"><h4>Politique</h4><form data-governance data-planet-id="${h(p.id)}" data-expected-governance="${h(p.governance)}"><div class="governance-choices"><button type="submit" name="governance" value="conseil" aria-pressed="${politics}" ${politics||locked?'disabled':''}>Conseil</button><button type="submit" name="governance" value="tyrannie" aria-pressed="${!politics}" ${!politics||locked?'disabled':''}>Tyrannie</button></div>${locked?`<small class="governance-lock">Prochain changement : ${new Date(new Date(p.governance_changed_at).getTime()+72*3600000).toLocaleString('fr-FR')}</small>`:''}<p class="governance-effects"><span>Croissance ${politics?'+20 %':'−20 %'}</span><span>Recrutement ${politics?'−20 %':'+20 %'}</span></p>${growth?`<div class="growth-details"><strong>+${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(growth.daily_people)} habitants / jour</strong><br>${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:3}).format(growth.daily_rate*100)} % / jour${growth.war?' · Croissance arrêtée par la guerre':growth.nearby_war?' · Croissance réduite par les combats proches':''}</div>`:''}${errorBox}</form>${pendingGovernance?'<button class="text-button" id="resume-governance">Reprendre le choix politique</button>':''}</div><div class="planet-control-module"><h4>Civilisation <span>${civilizationBadge()} ${p.civilization}</span></h4>${civilizationInvestmentView(civilization,progression?.server_now,true)}<button class="text-button" data-page="civilization">Toutes vos civilisations →</button></div></section>
 <section class="stat-section"><div class="section-heading"><h3>Économie & commerce</h3></div><div class="planet-control-module"><h4>Capacités commerciales</h4><div class="planet-capacity-summary"><span>${used} utilisées</span><strong>+${available} disponibles</strong></div><div class="capacity-track planet-capacity-track" role="img" aria-label="${used} capacités utilisées et ${available} disponibles">${capacityBlocks(used,'engaged')}${capacityBlocks(available,'free')}</div><p class="planet-capacity-total">${capacity} / 200 capacités</p>${capacity<200?`<form data-planet-capacity data-planet-id="${h(p.id)}" data-capacity="${capacity}"><label>Capacités à créer<input name="quantity" type="number" min="1" max="${200-capacity}" step="1" value="1" required></label><strong data-planet-capacity-cost>${quote===null?'…':money(quote)}</strong><button class="secondary" type="submit" ${quote===null?'disabled':''}>Créer →</button>${errorBox}</form>`:'<p class="section-note">Capacité maximale atteinte.</p>'}${pendingPurchase?'<button id="resume-planet-economic" class="text-button">Reprendre la commande</button>':''}<button class="text-button" data-planet-trade="${h(p.id)}">Gérer les liaisons →</button></div></section>
 <section class="stat-section"><div class="section-heading"><h3>Garnison</h3></div><div class="planet-forces">${[['Soldat',p.soldiers],['Scout',p.scouts],['Bombardier',p.bombers],['Destroyer',p.fighters]].map(([name,quantity])=>`<div><span>${name}</span><strong>${number(quantity)}</strong></div>`).join('')}</div><p class="section-note">${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(p.daily_recruits||0)} soldats / jour</p><button class="text-button" data-page="fleets">Gérer les forces →</button></section>
 <section class="stat-section"><div class="section-heading"><h3>Énergie</h3></div><div class="planet-energy"><strong>${p.energy}</strong><span>/ ${p.energy_max}</span></div><p class="section-note">${technology?.energy_unlocked?'Recharge : +1 charge / h':'Recharge verrouillée'}</p>${technology?.energy_unlocked&&p.energy_max<100?`<form class="planet-energy-form" data-technology="energy_capacity" data-planet="${h(p.id)}" data-capacity="${p.energy_max}"><input type="hidden" name="expected_capacity" value="${p.energy_max}"><label>Places à ajouter <input name="quantity" type="number" min="1" max="${100-p.energy_max}" value="1" step="1" required></label><strong data-energy-quote>${number(technology.energy_prices[p.energy_max+1])} Þ</strong><button class="secondary" type="submit">Agrandir →</button>${errorBox}</form>`:''}<button class="text-button planet-technology-link" data-open-technology>${technology?.energy_unlocked?'Technologies & téléportation →':'Débloquer la recharge →'}</button></section></div>`;
}
export function bindPlanetCapacityQuotes(root,overview){root.querySelectorAll('form[data-planet-capacity]').forEach(form=>{form.querySelector('input').addEventListener('input',e=>{const quote=planetCapacityQuote(Number(form.dataset.capacity),e.target.value,overview.prices);form.querySelector('[data-planet-capacity-cost]').textContent=quote===null?'Quantité invalide':money(quote);});});}
